let lang=localStorage.getItem('economic-relay.lang')==='kk'?'kk':'ru';
let pub=null,admin=null,member=null,view='overview',teamIndex=0,taskDraft=null,questionDraft=null,quizIndex=0,quizAnswers={},dirty=false,poll=null,openTaskIndex=0;
const $=id=>document.getElementById(id);
const L=key=>(lang==='kk'?KK:RU)[key]||key;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(v,n=200)=>esc(String(v??'').slice(0,n));
function note(message){const el=$('toast');el.textContent=message;el.style.display='block';clearTimeout(note.timer);note.timer=setTimeout(()=>el.style.display='none',4200);}
function errText(code){return L('err_'+code)!=='err_'+code?L('err_'+code):code||L('errDefault');}
async function api(url,method='GET',body){let res;try{res=await fetch('/api'+url,{method,credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});}catch{throw Error('network');}
  let data;try{data=await res.json();}catch{throw Error('network');}if(!res.ok)throw Error(data.error||'network');return data;}
async function post(url,body,after){try{const result=await api(url,'POST',body);if(after)after(result);await refresh();note(L('saved'));return result;}catch(ex){note(errText(ex.message));return null;}}
function setLanguage(code){lang=code;localStorage.setItem('economic-relay.lang',lang);render();}
function header(){document.documentElement.lang=lang;$('brandSecret').textContent=lang==='ru'?'ЭКОНОМИЧЕСКАЯ ЭСТАФЕТА':'ЭКОНОМИКАЛЫҚ ЭСТАФЕТА';$('stageCaption').textContent=lang==='ru'?'2 ТУР / 2 КЕЗЕҢ':'2 КЕЗЕҢ / 2 ТУР';$('heroKicker').textContent=L('kicker');$('heroHeading').innerHTML=L('heading');$('heroCaption').textContent=L('caption');$('factQuestions').textContent=L('questions');$('factTeamsLabel').textContent=L('teams');$('factTasksLabel').textContent=L('tasks');$('factTeams').textContent=admin?.teams.length||(pub?.teams?.length||'—');$('factTasks').textContent=admin?admin.teams.reduce((sum,t)=>sum+t.tasks.length,0):member?member.team.taskCount:pub?.leaderboard?.length?pub.leaderboard.reduce((n,x)=>n+x.taskCount,0):'—';$('langRu').classList.toggle('active',lang==='ru');$('langKk').classList.toggle('active',lang==='kk');$('signout').classList.toggle('hidden',!pub?.teacher&&!pub?.member);$('loginHeading').textContent=L('teacherLogin');$('loginCaption').textContent=L('teacherPass');$('passwordLabel').textContent=L('password');$('loginSubmit').textContent=L('login')+' →';}
async function refresh(){try{pub=await api('/public');admin=pub.teacher?await api('/admin'):null;member=pub.member?await api('/member'):null;
 if(admin&&!taskDraft){taskDraft=structuredClone(admin.teams).map(t=>({id:t.id,name:t.name,pin:t.pin,tasks:t.tasks.map(k=>({id:k.id,ru:k.ru,kk:k.kk,officialId:k.officialId}))}));}
 if(admin&&!questionDraft)questionDraft=structuredClone(admin.questions);render();
}catch(ex){note(errText(ex.message));$('app').innerHTML=`<div class="panel note bad">${esc(errText(ex.message))}</div>`;}}
function render(){header();$('app').innerHTML=!pub?'<div class="loading">Loading...</div>':pub.teacher?teacherUI():pub.member?memberUI():ttest?ttestUI():landingUI();}
function field(label,id,value='',type='text',hint='',attrs=''){return `<div class="form-field"><label class="label" for="${id}">${esc(label)}</label><input id="${id}" class="input" type="${type}" value="${esc(value)}" ${attrs}>${hint?`<div class="hint">${esc(hint)}</div>`:''}</div>`;}
function card(title,desc,content,extra=''){return `<section class="panel ${extra}"><h2>${title}</h2>${desc?`<p class="subdued">${desc}</p>`:''}${content||''}</section>`;}
function board(){const items=pub?.leaderboard||[];return card('🏆 '+L('ranking'),L('rankingDesc'),items.length?items.map((x,i)=>`<div class="leader-row"><div class="leader-position">${i+1}</div><div class="leader-info"><b>${esc(x.name)}</b><div class="subdued minor">${x.completed}/${x.taskCount} ${L('done')} · ${x.members} ${L('participants')}</div><div class="bar"><i style="width:${Math.max(0,Math.min(100,100*(x.score||0)/Math.max(10,x.maxScore)))}%"></i></div></div><div class="leader-score">${x.score??0} / ${x.maxScore}</div></div>`).join(''):`<p class="subdued">${L('noRanking')}</p>`);}
function landingUI(){const open=pub.phase==='open';return `<div class="grid">${card('🎓 '+L('student'),L('studentDesc'),open?`<div class="note good mb15">✓ ${L('opened')}</div><form id="joinForm" onsubmit="joinTeam(event)">${field(L('name'),'name','','text','', 'required minlength="2" maxlength="90" autocomplete="name"')}<div class="form-field"><label class="label" for="selectTeam">${L('selectTeam')}</label><select class="input" id="selectTeam" required><option value="">—</option>${pub.teams.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div>${field(L('pin'),'pin','','text','','required minlength="4" maxlength="32" autocomplete="off"')}<button class="btn primary full" type="submit">${L('join')} →</button></form>`:`<div class="icon-circle">🔒</div><h3>${L('waiting')}</h3><p class="subdued">${L('waitingText')}</p><span class="pill amber">⏳ ${L('prep')}</span>`)}${ttestCard()}${board()}</div>`;}
function teacherUI(){const tabs=[['overview','⌂',L('overview')],['tasks','▦',L('assignments')],['reviews','✎',L('reviews')],['teachers','👩‍🏫',L('ttTab')],['settings','⚙',L('settings')]];return `<div class="teacher-strip"><div><h2>👩‍🏫 ${L('teacherPanel')}</h2><div class="subdued">${L('teacherSub')}</div></div><span class="pill">${L('round')} ${admin.round}</span></div><nav class="nav-pills">${tabs.map(([id,icon,label])=>`<button type="button" class="${view===id?'selected':''}" onclick="changeView('${id}')">${icon}&nbsp; ${label}</button>`).join('')}</nav>${view==='tasks'?tasksUI():view==='reviews'?reviewsUI():view==='settings'?settingsUI():view==='teachers'?ttAdminUI():view==='quiz'?quizUI():overviewUI()}`;}
function badgePhase(){return admin.phase==='setup'?`<span class="pill amber">${L('prep')}</span>`:admin.phase==='quiz_done'?`<span class="pill">${L('quizCompleted')}</span>`:admin.phase==='open'?`<span class="pill green">● ${L('opened')}</span>`:`<span class="pill gray">${L('closed')}</span>`;}
function overviewUI(){const prepared=admin.teams.reduce((n,x)=>n+x.tasks.length,0),completed=admin.teams.reduce((n,x)=>n+x.tasks.filter(k=>!!k.submission).length,0),graded=admin.teams.reduce((n,x)=>n+x.tasks.filter(k=>k.submission?.score!=null).length,0),registered=admin.teams.reduce((n,x)=>n+x.members.length,0);const phase=admin.phase;
 return `<div class="numbers"><div class="number-tile"><span>👥 ${L('registered')}</span><b>${registered}</b></div><div class="number-tile"><span>📚 ${L('prepared')}</span><b>${prepared}</b></div><div class="number-tile"><span>📨 ${L('received')}</span><b>${completed}</b></div><div class="number-tile"><span>🏅 ${L('graded')}</span><b>${graded}</b></div></div><div class="panel"><div class="row spread"><h2>✦ ${L('welcome')}</h2>${badgePhase()}</div><div class="flow-steps"><div class="flow-step ${phase!=='setup'?'done':'now'}"><div class="rounddot">1</div><div><strong>${L('prep')}</strong><p>${L('beforeLesson')}</p></div></div><div class="flow-step ${admin.quiz.completed?'done':phase==='setup'?'':'now'}"><div class="rounddot">2</div><div><strong>${L('quizStep')}</strong><p>${L('quizHelp')}</p></div></div><div class="flow-step ${phase==='open'?'done':phase==='quiz_done'?'now':''}"><div class="rounddot">3</div><div><strong>${L('gameStep')}</strong><p>${L('openHint')}</p></div></div></div><div class="row mt25">${phase==='setup'?`<button class="btn ghost" onclick="changeView('tasks')">▦ ${L('goTasks')}</button><button class="btn primary" onclick="changeView('quiz')">🧠 ${L('goQuiz')}</button>`:phase==='quiz_done'?`<div class="note good">✓ ${L('quizFinished')} ${admin.quiz.score}/20</div><button class="btn green" onclick="openGame()">🔓 ${L('open')}</button>`:phase==='open'?`<button class="btn softred" onclick="closeGame()">◼ ${L('close')}</button>`:`<button class="btn green" onclick="openGame()">↻ ${L('reopen')}</button>`}</div>${admin.quiz.completed?`<p class="subdued mt15">🧠 ${L('quizScore')}: <b>${admin.quiz.score}/20</b>. ${L('quizNotPoints')}</p>`:''}</div><div class="grid mt25">${shareUI()}${board()}</div>`;}
function shareUI(){return card('🔗 '+L('share'),L('shareDesc'),`<div class="share-row"><img class="qr" src="/api/qr" alt="QR"><div class="share-text"><div class="linkbox">${esc(location.origin)}</div><button class="btn ghost mt15" onclick="copyLink()">⧉ ${L('copyLink')}</button></div></div>`);}
function changeView(next){view=next;render();document.getElementById('app').scrollIntoView({behavior:'smooth',block:'start'});}
function ensureDraft(){if(!taskDraft)taskDraft=structuredClone(admin.teams).map(t=>({id:t.id,name:t.name,pin:t.pin,tasks:t.tasks.map(k=>({id:k.id,ru:k.ru,kk:k.kk,officialId:k.officialId}))}));}
function tasksUI(){ensureDraft();const locked=admin.phase!=='setup';const team=taskDraft[Math.max(0,Math.min(teamIndex,taskDraft.length-1))];return `<div class="row spread mb15"><div><h2 class="section-title" style="margin-bottom:4px">📚 ${L('taskEditor')}</h2><p class="subdued" style="margin:0">${L('taskEditorDesc')}</p></div><span class="pill ${locked?'gray':dirty?'amber':'green'}">${locked?'🔒':dirty?'●':'✓'} ${locked?L('editBlocked'):dirty?L('unsaved'):L('saved')}</span></div>${locked?`<div class="note warn mb15">${L('editBlocked')}</div>`:''}${!locked?officialImportUI():''}<div class="task-layout"><aside class="team-sidebar"><h3>КОМАНДЫ / КОМАНДАЛАР</h3><div>${taskDraft.map((x,i)=>`<button type="button" onclick="chooseTeam(${i})" class="${i===teamIndex?'selected':''}"><span>${i+1}. ${esc(x.name||'—')}</span> <span class="count">${x.tasks.length}</span></button>`).join('')}</div>${!locked?`<button class="btn outline full mt15" style="color:#fff;border-color:#ffffff55;background:#ffffff15;justify-content:center" onclick="addTeam()">${L('addTeam')}</button>`:''}</aside><div class="panel"><div class="row spread"><h2>${esc(team.name||L('teamName'))}</h2><span class="pill">${team.tasks.length}/30 ${L('tasks')}</span></div>${field(L('teamName'),'teamName',team.name,'text','','oninput="editTeam(\'name\',this.value)" '+(locked?'disabled':''))}${field(L('teamPin'),'teamPin',team.pin,'text','','oninput="editTeam(\'pin\',this.value)" '+(locked?'disabled':''))}<div class="row spread mt25"><h3>📖 ${L('taskCount')}: ${team.tasks.length}</h3>${!locked?`<button class="btn ghost small" onclick="addTask()">${L('addTask')}</button>`:''}</div><p class="subdued minor">${L('taskHint')}</p>${team.tasks.map((task,i)=>`<details class="task-card" ${i===openTaskIndex?'open':''}><summary>✦ ${L('taskNumber')} ${i+1} ${task.officialId?'<span class="pill green">50 / 50</span>':''} ${task.ru||task.kk?`<span class="subdued minor" style="font-weight:500">${esc((task[lang]||task.ru||task.kk).slice(0,58))}</span>`:''}</summary><div class="task-card-body"><div class="two-fields"><div class="form-field"><label class="label">🇷🇺 ${L('taskRu')}</label><textarea class="input" maxlength="3000" ${locked?'disabled':''} oninput="editTask(${i},'ru',this.value)">${esc(task.ru)}</textarea></div><div class="form-field"><label class="label">🇰🇿 ${L('taskKk')}</label><textarea class="input" maxlength="3000" ${locked?'disabled':''} oninput="editTask(${i},'kk',this.value)">${esc(task.kk)}</textarea></div></div>${!locked&&team.tasks.length>1?`<div class="row spread"><span></span><button class="btn softred small" onclick="removeTask(${i})">× ${L('deleteTask')}</button></div>`:''}</div></details>`).join('')}${!locked?`<button class="btn ghost full mt15" onclick="addTask()">${L('addTask')}</button><div class="bulkin mt25"><h3>⚡ ${L('bulkTitle')}</h3><p class="subdued minor">${L('bulkHelp')}</p><textarea class="input" id="bulkTasks" placeholder="${esc(L('bulkPlaceholder'))}"></textarea><button class="btn dark small mt15" onclick="bulkAdd()">${L('bulkAdd')} →</button></div><div class="sticky-controls mt25"><button class="btn softred small" onclick="removeTeam()">× ${L('deleteTeam')}</button><button class="btn green" onclick="saveTeams()">💾 ${L('saveAll')}</button></div>`:''}</div></div>`;}
function officialImportUI(){
 return `<section class="official-import panel mb15"><div><h3>📂 ${L('officialPack')}</h3><p class="subdued">${L('officialHelp')}</p></div><div class="row"><label class="label" for="officialTeamCount">${L('officialCount')}</label><select class="input small-select" id="officialTeamCount"><option value="7" ${admin.teams.length!==10?'selected':''}>7</option><option value="10" ${admin.teams.length===10?'selected':''}>10</option></select><button class="btn green" onclick="loadOfficialTasks()">✦ ${L('loadOfficial')}</button></div></section>`;
}
async function loadOfficialTasks(){
 if(!confirm(L('officialConfirm')))return;
 const count=Number($('officialTeamCount').value);
 try{await api('/admin/tasks/official','POST',{count});taskDraft=null;teamIndex=0;openTaskIndex=0;dirty=false;await refresh();note(L('officialReady'));}
 catch(ex){note(errText(ex.message));}
}
function chooseTeam(i){teamIndex=i;openTaskIndex=0;render();}
function touch(){dirty=true;}
function editTeam(k,v){taskDraft[teamIndex][k]=v;touch();}
function editTask(i,k,v){taskDraft[teamIndex].tasks[i][k]=v;touch();}
function addTask(){const team=taskDraft[teamIndex];if(team.tasks.length>=30){note(L('err_tasks_count'));return;}team.tasks.push({id:Math.max(0,...team.tasks.map(x=>x.id||0))+1,ru:'',kk:''});openTaskIndex=team.tasks.length-1;dirty=true;render();}
function removeTask(i){if(taskDraft[teamIndex].tasks.length===1)return;if(!confirm(L('deleteTask')+'?'))return;taskDraft[teamIndex].tasks.splice(i,1);openTaskIndex=0;dirty=true;render();}
function addTeam(){if(taskDraft.length>=20){note(L('err_teams_count'));return;}const code=String(100000+crypto.getRandomValues(new Uint32Array(1))[0]%900000);taskDraft.push({id:null,name:'',pin:code,tasks:[{id:1,ru:'',kk:''}]});teamIndex=taskDraft.length-1;openTaskIndex=0;dirty=true;render();}
function removeTeam(){if(taskDraft.length===1||!confirm(L('deleteTeam')+'?'))return;taskDraft.splice(teamIndex,1);teamIndex=0;dirty=true;render();}
function bulkAdd(){const txt=$('bulkTasks')?.value.trim();if(!txt)return;const split=txt.includes('\n\n')?txt.split(/\n\s*\n/):txt.split(/\n+/);const chunks=split.map(x=>x.trim()).filter(Boolean);const team=taskDraft[teamIndex];const blank=team.tasks.length===1&&!team.tasks[0].ru.trim()&&!team.tasks[0].kk.trim();if(team.tasks.length+chunks.length-(blank?1:0)>30){note(L('err_tasks_count'));return;}let id=Math.max(0,...team.tasks.map(k=>k.id||0));if(blank){const first=chunks.shift();team.tasks[0][lang]=first;}chunks.forEach(x=>team.tasks.push({id:++id,ru:lang==='ru'?x:'',kk:lang==='kk'?x:''}));openTaskIndex=blank?0:team.tasks.length-1;dirty=true;render();note(L('bulkSuccess'));}
async function saveTeams(){if(taskDraft.some(t=>!t.name.trim()||!t.pin.trim()||t.pin.length<4||!t.tasks.length||t.tasks.some(k=>!k.ru.trim()&&!k.kk.trim()))){note(L('saveRequired'));return;}try{await api('/admin/teams','POST',{teams:taskDraft});taskDraft=null;dirty=false;await refresh();note(L('saved'));}catch(ex){note(errText(ex.message));}}
function quizUI(){if(admin.quiz.completed)return quizResultUI();const q=admin.questions[quizIndex];return `<div class="question"><div class="row spread mb15"><button class="btn outline small" onclick="changeView('overview')">${L('goBack')}</button><span class="pill">${L('question')} ${quizIndex+1}/20</span></div><div class="panel"><h2>🧠 ${L('testTitle')}</h2><p class="subdued">${L('testDesc')}</p><div class="progress-track mt25"><span style="width:${(quizIndex+1)*5}%"></span></div><div class="quiz-section">${L(quizIndex<7?'section1':quizIndex<14?'section2':'section3')}</div><h3 class="mt15" style="font-size:19px">${quizIndex+1}. ${esc(q[lang])}</h3>${q['options_'+lang].map((option,i)=>`<label class="choice"><input type="radio" name="opt" ${quizAnswers[quizIndex]===i?'checked':''} onchange="quizChoose(${i})"> <span><strong class="answer-letter">${['А','Б','В','Г','Д'][i]})</strong> ${esc(option)}</span></label>`).join('')}<div class="row spread mt25"><button class="btn outline" ${quizIndex===0?'disabled':''} onclick="quizMove(-1)">← ${L('back')}</button><button class="btn primary" onclick="quizMove(1)">${quizIndex===19?L('completeQuiz')+' ✓':L('next')+' →'}</button></div><div class="subdued minor mt15">${Object.keys(quizAnswers).length}/20</div></div></div>`;}
function quizChoose(i){quizAnswers[quizIndex]=i;}
function quizMove(delta){if(delta>0&&!Number.isInteger(quizAnswers[quizIndex])){note(L('answerMissing'));return;}if(quizIndex===19&&delta>0){finishQuiz();return;}quizIndex=Math.max(0,Math.min(19,quizIndex+delta));render();}
async function finishQuiz(){const answers=Array.from({length:20},(_,i)=>quizAnswers[i]);if(answers.some(x=>!Number.isInteger(x))){note(L('incompleteQuiz'));return;}if(!confirm(L('completeQuiz')+'?'))return;try{await api('/admin/quiz','POST',{answers});view='quiz';await refresh();}catch(ex){note(errText(ex.message));}}
function quizResultUI(){return `<div class="panel"><div class="row spread"><div><h2>🎉 ${L('quizFinished')}</h2><p class="subdued">${L('quizNotPoints')}</p></div><div class="score-number">${admin.quiz.score}<small style="font-size:18px;color:#969bb8">/20</small></div></div><div class="note good mt15"><b>${L('level')}:</b> ${L(admin.quiz.score>=18?'gradeHigh':admin.quiz.score>=14?'gradeGood':admin.quiz.score>=10?'gradeBasic':'gradeRepeat')}</div><div class="row mt15"><button class="btn ghost" onclick="changeView('overview')">${L('goBack')}</button>${admin.phase==='quiz_done'?`<button class="btn green" onclick="openGame()">🔓 ${L('open')}</button>`:''}</div><h3 class="mt25">${L('correctAnswers')}</h3>${admin.questions.map((q,i)=>`<details class="advanced"><summary>${i+1}. ${esc(q[lang])}</summary><p class="subdued"><b>${L('correct')}:</b> ${['А','Б','В','Г','Д'][q.correct]}) ${esc(q['options_'+lang][q.correct])}</p><p class="subdued">${L('yourAnswer')}: ${['А','Б','В','Г','Д'][admin.quiz.answers[i]]||'—'}) ${esc(q['options_'+lang][admin.quiz.answers[i]]||'—')}</p></details>`).join('')}</div>`;}
async function openGame(){if(!confirm(L('open')+'?'))return;await post('/admin/open',{});}
async function closeGame(){if(!confirm(L('close')+'?'))return;await post('/admin/close',{});}
function officialKeyHtml(task){
 if(!task.officialId)return '';if(!admin.answerKeys?.[task.officialId])return `<p class="subdued minor">🔐 ${L('keysMissing')}</p>`;
 const answers=admin.answerKeys[task.officialId][lang]||[];
 return `<details class="judge-key"><summary>🔐 ${L('judgeKey')}</summary>${answers.map((a,i)=>`<div class="key-part"><strong>${L(['analysis','calculation','decision'][i])}</strong><p>${esc(a)}</p></div>`).join('')}<p class="subdued minor">${esc(admin.officialGuide?.[lang]?.judgeNote||'')}</p></details>`;
}
function rubricInputs(team,task){
 const rubric=task.submission?.rubric||{};
 const fields=[['analysis',10],['calculation',15],['decision',15],['defense',10]];
 return `<div class="rubric"><h4>${L('officialRubric')}</h4><p class="subdued minor">${L('rubricGuide')}</p><div class="rubric-grid">${fields.map(([key,max])=>`<label class="rubric-field"><span>${L(key)} <small>/ ${max}</small></span><input class="input" type="number" min="0" max="${max}" step="1" inputmode="numeric" id="r_${key}_${team.id}_${task.id}" value="${rubric[key]??''}" placeholder="0–${max}"></label>`).join('')}</div></div>`;
}
function reviewsUI(){
 const total=admin.teams.reduce((n,t)=>n+t.score,0);
 return `<div class="row spread mb15"><div><h2 class="section-title" style="margin-bottom:4px">📝 ${L('reviewTitle')}</h2><p class="subdued" style="margin:0">${L('reviewDesc')}</p></div><button class="btn ghost small" onclick="refresh()">↻ ${L('refresh')}</button></div>
 <div class="panel"><div class="row spread"><h3>🏆 ${L('total')}: ${total}</h3><a class="btn outline small" href="/api/admin/csv" download>↓ Excel / CSV</a></div>
 ${admin.teams.map((team,i)=>`<details class="review-team" ${i===0?'open':''}><summary>🏳️ ${esc(team.name)} <span class="pill" style="float:right">${team.score} / ${team.maxScore}</span></summary><div class="review-body"><p class="subdued"><b>${L('members')}:</b> ${team.members.length?team.members.map(m=>`${esc(m.name)} ${m.isCaptain?'★':''} <button class="btn ghost small" onclick="memberAction(${team.id},${m.id},'captain')" title="${L('promote')}">♛</button>`).join(' · '):'—'}</p>
 ${team.tasks.map((task,j)=>`<div class="task-item"><div class="row spread"><h4>📚 ${L('taskNumber')} ${j+1} ${task.officialId?`· ${L('officialScore')}`:''}</h4><span class="pill ${task.submission?.score!=null?'green':task.submitted?'amber':'gray'}">${task.submission?.score!=null?task.submission.score+'/'+task.maxScore:task.submitted?L('awaiting'):L('noAnswer')}</span></div>
 ${task.officialId?`<p class="subdued">${esc(task.officialContent?.[lang]?.title||'')}</p>`:`<p class="subdued prewrap">${esc(task[lang]||task.ru||task.kk)}</p>`}
 ${officialKeyHtml(task)}
 ${task.submitted?`<div class="submission prewrap">${esc(task.submission.answer||'📷')}</div>${task.submission.hasPhoto?`<a target="_blank" rel="noopener" href="/api/photo/${team.id}/${task.id}"><img class="photo" src="/api/photo/${team.id}/${task.id}" loading="lazy" alt="${L('photo')}"></a>`:''}
 ${task.officialId?rubricInputs(team,task):`<div class="form-field"><label class="label">${L('gradeLabel')}</label><input type="number" min="0" max="10" step="1" class="input" id="score_${team.id}_${task.id}" value="${task.submission.score??''}"></div>`}
 <div class="form-field"><label class="label">${L('feedback')}</label><textarea class="input" id="feedback_${team.id}_${task.id}" maxlength="1500">${esc(task.submission.feedback||'')}</textarea></div>
 <button class="btn green small" onclick="grade(${team.id},${task.id})">✓ ${L('saveGrade')}</button>`:`<p class="subdued">⏳ ${L('noAnswer')}</p>`}</div>`).join('')}</div></details>`).join('')}</div>`;
}
async function grade(teamId,taskId){
 const task=admin.teams.find(t=>t.id===teamId)?.tasks.find(t=>t.id===taskId);
 if(!task)return;
 const body={teamId,taskId,feedback:$(`feedback_${teamId}_${taskId}`).value};
 if(task.officialId){
   const caps={analysis:10,calculation:15,decision:15,defense:10};
   body.rubric={};
   for(const [key,max] of Object.entries(caps)){
     const el=$(`r_${key}_${teamId}_${taskId}`),n=Number(el?.value);
     if(!el||el.value===''||!Number.isInteger(n)||n<0||n>max){note(L('rubricIncomplete'));return;}
     body.rubric[key]=n;
   }
 }else{
   const el=$(`score_${teamId}_${taskId}`),n=Number(el?.value);
   if(!el||el.value.trim()===''||!Number.isInteger(n)||n<0||n>10){note(L('err_score_range'));return;}
   body.score=n;
 }
 await post('/admin/grade',body);
}
async function memberAction(teamId,memberId,action){if(!confirm(L('promote')+'?'))return;await post('/admin/member',{teamId,memberId,action});}
function officialTaskPanel(active){
 const content=active.officialContent?.[lang]||active.officialContent?.ru;
 if(!content)return `<div class="task-preview prewrap">${esc(active[lang]||active.ru||active.kk)}</div>`;
 return `<div class="official-stage-header"><span class="pill green">${L('officialScore')}</span><h3>${esc(content.title)}</h3></div>
 <div class="stages">${content.stages.map((v,i)=>`<section class="stage-box stage-${i+1}"><div class="stage-chip">${i+1}</div><div><h4>${esc(v.heading)}</h4><p class="prewrap">${esc(v.body)}</p></div></section>`).join('')}</div>
 <div class="oral-note"><strong>🎤 ${L('oralTitle')}</strong><p>${L('oralHelp')}</p></div>`;
}
function memberUI(){
 const data=member,team=data.team,me=data.me;
 const active=team.tasks.find(k=>k.id===team.activeId);
 const completed=team.tasks.filter(k=>k.submitted).length;
 const progress=team.tasks.map(k=>`<span class="${k.submitted?'done':k.id===team.activeId?'active':''}" title="${L('taskNumber')} ${k.id}"></span>`).join('');
 const roster=data.members.map(m=>esc(m.name)+(m.isCaptain?' ★':'')).join(' · ');
 const current=active?`<div class="row spread mt25"><h3>✦ ${L('currentTask')} ${completed+1}</h3><span class="pill">${completed+1}/${team.taskCount}</span></div>${active.officialId?officialTaskPanel(active):`<div class="task-preview prewrap">${esc(active[lang]||active.ru||active.kk)}</div>`}`:`<div class="note good mt25"><h3>🎉 ${L('allSubmitted')}</h3>${L('allSubmittedText')}</div>`;
 const routeHtml=`<h3>${L('taskProgress')}: ${completed}/${team.taskCount}</h3><div class="task-meter">${progress}</div><div class="progress-track"><span style="width:${Math.round(100*completed/team.taskCount)}%"></span></div><p class="subdued minor">${roster}</p>${current}`;
 let answerHtml='';
 if(active){
   if(me.isCaptain&&data.phase==='open'){
     const inputs=active.officialId?`<div class="note mb15">${L('officialCardInfo')}</div>${['analysis','calculation','decision'].map((key,i)=>`<div class="form-field"><label class="label" for="stageAnswer${i}">${L(key)}</label><textarea id="stageAnswer${i}" class="input" maxlength="3600" placeholder="${L(['analysisInput','calculationInput','decisionInput'][i])}" style="min-height:110px"></textarea></div>`).join('')}`:`<div class="form-field"><label class="label" for="answerText">${L('typeAnswer')}</label><textarea id="answerText" class="input" maxlength="12000" placeholder="..." style="min-height:160px"></textarea></div>`;
     answerHtml=`<div class="note mb15">${L('captainOnly')}</div>${inputs}<div class="form-field"><label class="label" for="answerPhoto">${active.officialId?L('posterPhoto'):L('attach')}</label><input class="input" type="file" accept="image/jpeg,image/png,image/webp" id="answerPhoto"></div><button class="btn green full" id="sendAnswerButton" onclick="submitAnswer(${active.id})">${completed+1===team.taskCount?L('sendLast'):L('sendNext')}</button>`;
   }else{answerHtml=`<div class="note warn">${data.phase!=='open'?L('waitForTeacher'):L('notCaptain')}</div>`;}
 }else{answerHtml=`<div class="icon-circle teal">🏅</div><h3>${L('allSubmitted')}</h3><p class="subdued">${L('allSubmittedText')}</p>`;}
 const history=team.tasks.filter(k=>k.submitted).map(k=>{const sub=k.submission;return `<div class="task-item"><div class="row spread"><b>${L('taskNumber')} ${team.tasks.indexOf(k)+1}</b><span class="pill ${sub?.score!=null?'green':'amber'}">${sub?.score!=null?sub.score+'/'+k.maxScore:L('awaiting')}</span></div><div class="submission prewrap">${esc(sub?.answer||'📷')}</div>${sub?.hasPhoto?`<img class="photo" src="/api/photo/${team.id}/${k.id}" loading="lazy" alt="${L('photo')}">`:''}${sub?.feedback?`<p class="subdued">💬 ${esc(sub.feedback)}</p>`:''}</div>`;}).join('')||`<p class="subdued">${L('noAnswer')}</p>`;
 answerHtml+=`<div class="mt25"><h3>${L('myResults')}</h3>${history}</div>`;
 return `<div class="teacher-strip"><div><h2>🏳️ ${esc(team.name)}</h2><p class="subdued" style="margin:0">${me.isCaptain?'★ '+L('captain'):L('participants')}: ${esc(me.name)}</p></div><span class="pill green">${L('round')} ${data.round}</span></div><div class="student-main">${card('📚 '+L('yourRoute'),'',routeHtml)}${card('✍️ '+L('answer'),'',answerHtml)}</div><div class="row mt25"><button class="btn ghost" onclick="refresh()">↻ ${L('refresh')}</button></div><div class="mt25">${board()}</div>`;
}
async function submitAnswer(taskId){
 const active=member?.team?.tasks.find(k=>k.id===taskId);
 let answer=active?.officialId?['analysis','calculation','decision'].map((key,i)=>{
   const v=$(`stageAnswer${i}`)?.value.trim()||'';
   return v?`${L(key)}:\n${v}`:'';
 }).filter(Boolean).join('\n\n'):($('answerText')?.value.trim()||'');
 const input=$('answerPhoto'),file=input?.files[0];
 if(!answer&&!file){note(L('answerOrPhoto'));return;}
 if(file&&(file.size>2700000||!['image/jpeg','image/png','image/webp'].includes(file.type))){note(L('err_image_too_large'));return;}
 if(!confirm(L('sendConfirm')))return;
 let photo=null;
 if(file){try{photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}catch{note(L('errDefault'));return;}}
 const b=$('sendAnswerButton');b.disabled=true;
 try{await api('/member/submit','POST',{taskId,answer,photo});await refresh();note(L('saved'));}catch(ex){b.disabled=false;note(errText(ex.message));}
}
function settingsUI(){return `<div class="grid">${card('🔐 '+L('privateKeyTitle'),L('privateKeyHelp'),`<div class="row spread"><span class="pill">${L('keysAvailable')}: ${Object.keys(admin.answerKeys||{}).length}/10</span></div><div class="form-field"><input type="file" class="input" accept=".json,application/json" id="privateKeyFile"></div><button class="btn green" onclick="importAnswerKey()">🔒 ${L('importPrivateKey')}</button>`, 'private-keys-card')}${card('🛡 '+L('security'),'',`${field(L('oldPassword'),'oldPass','','password')}${field(L('newPassword'),'newPass','','password')}<button class="btn primary" onclick="changePassword()">${L('changePassword')}</button>`)}${card('📦 '+L('files'),'',`<div class="note ${admin.storage==='postgres'?'good':'bad'}">${admin.storage==='postgres'?L('dbPostgres'):L('dbLocal')}</div><div class="row mt25"><a class="btn ghost small" href="/api/admin/csv" download>↓ ${L('downloadCsv')}</a><a class="btn ghost small" href="/api/admin/export" download>↓ ${L('downloadJson')}</a></div>`)}${card('🔁 '+L('newRound'),L('newRoundInfo'),`<button class="btn softred" onclick="newRound()">↻ ${L('createRound')}</button>`)}${card('📁 '+L('history'),'',admin.history.length?admin.history.map(h=>`<div class="row spread mb15"><div><b>${L('round')} ${h.round}</b><div class="subdued minor">${new Date(h.finishedAt).toLocaleDateString()}</div></div><span class="pill">${h.teams.length} ${L('teams')}</span></div>`).join(''):'<p class="subdued">—</p>')}<section class="panel" style="grid-column:1/-1"><h2>🧠 ${L('editQuiz')}</h2><p class="subdued">${L('editQuizHelp')}</p>${questionDraft.map((q,i)=>`<details class="advanced"><summary>${i+1}. ${esc(q[lang])}</summary><div class="two-fields"><div class="form-field"><label class="label">${L('ruQuestion')}</label><textarea class="input" ${admin.phase!=='setup'?'disabled':''} oninput="editQuestion(${i},'ru',this.value)">${esc(q.ru)}</textarea></div><div class="form-field"><label class="label">${L('kkQuestion')}</label><textarea class="input" ${admin.phase!=='setup'?'disabled':''} oninput="editQuestion(${i},'kk',this.value)">${esc(q.kk)}</textarea></div></div><div class="two-fields">${['ru','kk'].map(locale=>`<div><h4>${locale.toUpperCase()}</h4>${q['options_'+locale].map((opt,j)=>`<div class="form-field"><label class="label">${j+1}</label><input class="input" value="${esc(opt)}" ${admin.phase!=='setup'?'disabled':''} oninput="editOption(${i},'${locale}',${j},this.value)"></div>`).join('')}</div>`).join('')}</div><div class="form-field"><label class="label">${L('correctOption')}</label><select class="input" ${admin.phase!=='setup'?'disabled':''} onchange="editQuestion(${i},'correct',Number(this.value))">${q.options_ru.map((_,x)=>`<option value="${x}" ${q.correct===x?'selected':''}>${['А','Б','В','Г','Д'][x]}</option>`).join('')}</select></div></details>`).join('')}${admin.phase==='setup'?`<div class="row mt25"><button class="btn green" onclick="saveQuestions()">💾 ${L('saveQuiz')}</button><button class="btn ghost" onclick="restoreOfficialQuiz()">↻ ${L('restoreOfficial')}</button></div>`:''}</section></div>`;}
async function importAnswerKey(){
 const file=$('privateKeyFile')?.files[0];if(!file)return;
 if(file.size>100000){note(L('err_invalid_answer_key'));return;}
 try{
   const json=JSON.parse(await file.text());
   await api('/admin/answers/import','POST',{answerKeys:json.answerKeys});
   await refresh();note(L('saved'));
 }catch(ex){note(errText(ex.message==='Unexpected token'?'invalid_answer_key':ex.message));}
}
function editQuestion(i,key,value){questionDraft[i][key]=value;}
function editOption(i,locale,index,value){questionDraft[i]['options_'+locale][index]=value;}
async function saveQuestions(){await post('/admin/questions',{questions:questionDraft});}
async function restoreOfficialQuiz(){if(!confirm(L('restoreOfficialConfirm')))return;try{await api('/admin/questions/official','POST',{});questionDraft=null;quizAnswers={};quizIndex=0;await refresh();note(L('saved'));}catch(ex){note(errText(ex.message));}}
async function changePassword(){const old=$('oldPass').value,next=$('newPass').value;if(next.length<10){note(L('newPassword'));return;}await post('/admin/password',{old,next});}
async function newRound(){if(!confirm(L('newRoundInfo'))||!confirm(L('createRound')+'?'))return;try{await api('/admin/next','POST',{confirm:'NEW ROUND'});view='overview';taskDraft=null;questionDraft=null;quizAnswers={};quizIndex=0;dirty=false;await refresh();note(L('saved'));}catch(ex){note(errText(ex.message));}}
async function joinTeam(event){event.preventDefault();const name=$('name').value.trim(),teamId=Number($('selectTeam').value),pin=$('pin').value.trim();if(!name||!teamId||!pin){note(L('saveRequired'));return;}try{await api('/member/register','POST',{name,teamId,pin});await refresh();}catch(ex){note(errText(ex.message));}}
async function teacherLogin(event){event.preventDefault();const password=$('teacherPassword').value;try{await api('/teacher/login','POST',{password});$('teacherDialog').close();$('teacherPassword').value='';view='overview';taskDraft=null;questionDraft=null;await refresh();}catch(ex){note(errText(ex.message));}}
async function logout(){if(dirty&&!confirm(L('unsaved')+'?'))return;try{await api('/logout','POST',{});}catch{}pub=null;admin=null;member=null;taskDraft=null;questionDraft=null;dirty=false;view='overview';await refresh();}
function copyLink(){navigator.clipboard?.writeText(location.origin).then(()=>note(L('saved'))).catch(()=>prompt('URL',location.origin))||prompt('URL',location.origin);}
