Object.assign(RU,{ttTab:'Тест учителей',ttTitle:'Тест для преподавателей',ttDesc:'Каждый преподаватель может пройти тест из 20 вопросов по экономике и финансовой грамотности. Введите ФИО — результат увидите сразу.',ttName:'ФИО преподавателя',ttCode:'Код доступа к тесту',ttStart:'Начать тест',ttExit:'Выйти из теста',ttExitConfirm:'Выйти? Ответы не сохранятся.',ttDone:'Готово',ttAgain:'Пройти ещё раз',ttResults:'Результаты преподавателей',ttResultsDesc:'Все попытки преподавателей, прошедших открытый тест. Эти баллы не влияют на рейтинг команд.',ttNone:'Пока никто не прошёл тест.',ttCount:'Прошли тест',ttAvg:'Средний балл',ttDate:'Дата',ttScore:'Балл',ttDelete:'Удалить',ttClear:'Удалить все результаты',ttClearConfirm:'Удалить ВСЕ результаты преподавателей? Это нельзя отменить.',ttCodeTitle:'Код доступа',ttCodeHelp:'Необязательно. Если задать код, тест смогут пройти только те, кому вы его сообщили. Оставьте пустым — тест открыт для всех.',ttSaveCode:'Сохранить код',ttLink:'Отправьте преподавателям ссылку на сайт — карточка теста на главной странице.',err_invalid_test_code:'Неверный код доступа к тесту.',err_code_too_short:'Код — минимум 4 символа.',err_try_later:'Слишком много попыток. Подождите несколько минут.'});
Object.assign(KK,{ttTab:'Мұғалімдер тесті',ttTitle:'Мұғалімдерге арналған тест',ttDesc:'Әр мұғалім экономика және қаржылық сауаттылық бойынша 20 сұрақтан тұратын тестті өте алады. Аты-жөніңізді енгізіңіз — нәтижені бірден көресіз.',ttName:'Мұғалімнің аты-жөні',ttCode:'Тестке кіру коды',ttStart:'Тестті бастау',ttExit:'Тесттен шығу',ttExitConfirm:'Шығасыз ба? Жауаптар сақталмайды.',ttDone:'Дайын',ttAgain:'Қайта өту',ttResults:'Мұғалімдердің нәтижелері',ttResultsDesc:'Ашық тестті өткен барлық мұғалімдердің нәтижелері. Бұл ұпайлар командалар рейтингіне әсер етпейді.',ttNone:'Әзірге ешкім тест өткен жоқ.',ttCount:'Тест өткендер',ttAvg:'Орташа балл',ttDate:'Күні',ttScore:'Балл',ttDelete:'Өшіру',ttClear:'Барлық нәтижені өшіру',ttClearConfirm:'Мұғалімдердің БАРЛЫҚ нәтижесін өшіру керек пе? Қайтару мүмкін емес.',ttCodeTitle:'Кіру коды',ttCodeHelp:'Міндетті емес. Код қойсаңыз, тестті тек кодты білетіндер өте алады. Бос қалдырсаңыз — тест барлығына ашық.',ttSaveCode:'Кодты сақтау',ttLink:'Мұғалімдерге сайт сілтемесін жіберіңіз — тест карточкасы басты бетте.',err_invalid_test_code:'Тест коды қате.',err_code_too_short:'Код кемі 4 таңба болуы керек.',err_try_later:'Әрекет тым көп. Бірнеше минут күтіңіз.'});
const TT_KEY='economic-relay.teacher-test';
let ttest=null;
try{const saved=JSON.parse(localStorage.getItem(TT_KEY)||'null');if(saved&&Array.isArray(saved.questions))ttest=saved;}catch{}
function ttSave(){try{ttest?localStorage.setItem(TT_KEY,JSON.stringify(ttest)):localStorage.removeItem(TT_KEY);}catch{}}
const LETTERS=['А','Б','В','Г','Д'];
function levelKey(score){return score>=18?'gradeHigh':score>=14?'gradeGood':score>=10?'gradeBasic':'gradeRepeat';}
function ttestCard(){return card('👩‍🏫 '+L('ttTitle'),L('ttDesc'),`<form id="ttForm" onsubmit="ttStart(event)">${field(L('ttName'),'ttName','','text','','required minlength="3" maxlength="120" autocomplete="name"')}${pub.teacherTestCode?field(L('ttCode'),'ttCode','','text','','required maxlength="60" autocomplete="off"'):''}<button class="btn primary full" type="submit">🧠 ${L('ttStart')} →</button></form>`,'tt-card');}
async function ttStart(event){event.preventDefault();const name=$('ttName').value.trim(),code=$('ttCode')?.value.trim()||'';if(name.length<3){note(L('ttName'));return;}
 try{const data=await api('/teacher-test/start','POST',{code});ttest={name,code,questions:data.questions,index:0,answers:{},result:null};ttSave();render();$('app').scrollIntoView({behavior:'smooth',block:'start'});}catch(ex){note(errText(ex.message));}}
function ttChoose(i){ttest.answers[ttest.index]=i;ttSave();}
function ttMove(delta){const n=ttest.questions.length;if(delta>0&&!Number.isInteger(ttest.answers[ttest.index])){note(L('answerMissing'));return;}if(ttest.index===n-1&&delta>0){ttFinish();return;}ttest.index=Math.max(0,Math.min(n-1,ttest.index+delta));ttSave();render();}
async function ttFinish(){const n=ttest.questions.length,answers=Array.from({length:n},(_,i)=>ttest.answers[i]);if(answers.some(x=>!Number.isInteger(x))){note(L('incompleteQuiz'));return;}if(!confirm(L('completeQuiz')+'?'))return;
 try{const r=await api('/teacher-test/submit','POST',{name:ttest.name,code:ttest.code,answers});ttest.result=r;ttSave();render();window.scrollTo({top:0,behavior:'smooth'});}catch(ex){note(errText(ex.message));}}
function ttExit(force){if(!force&&!ttest.result&&Object.keys(ttest.answers).length&&!confirm(L('ttExitConfirm')))return;ttest=null;ttSave();render();}
function ttAgain(){ttest={...ttest,index:0,answers:{},result:null};ttSave();render();}
function ttestUI(){const t=ttest,n=t.questions.length;
 if(t.result){const r=t.result;return `<div class="panel"><div class="row spread"><div><h2>🎉 ${L('quizFinished')}</h2><p class="subdued">👩‍🏫 ${esc(t.name)}</p></div><div class="score-number">${r.score}<small style="font-size:18px;color:#969bb8">/${r.total}</small></div></div><div class="note good mt15"><b>${L('level')}:</b> ${L(levelKey(r.score))}</div><div class="row mt15"><button class="btn primary" onclick="ttExit(true)">✓ ${L('ttDone')}</button><button class="btn ghost" onclick="ttAgain()">↻ ${L('ttAgain')}</button></div><h3 class="mt25">${L('correctAnswers')}</h3>${t.questions.map((q,i)=>{const ok=t.answers[i]===r.correct[i];return `<details class="advanced"><summary>${ok?'✅':'❌'} ${i+1}. ${esc(q[lang])}</summary><p class="subdued"><b>${L('correct')}:</b> ${LETTERS[r.correct[i]]}) ${esc(q['options_'+lang][r.correct[i]])}</p><p class="subdued">${L('yourAnswer')}: ${LETTERS[t.answers[i]]||'—'}) ${esc(q['options_'+lang][t.answers[i]]||'—')}</p></details>`;}).join('')}</div>`;}
 const q=t.questions[t.index];
 return `<div class="question"><div class="row spread mb15"><button class="btn outline small" onclick="ttExit()">← ${L('ttExit')}</button><span class="pill">${L('question')} ${t.index+1}/${n}</span></div><div class="panel"><h2>🧠 ${L('testTitle')}</h2><p class="subdued">👩‍🏫 ${esc(t.name)} · ${L('testDesc')}</p><div class="progress-track mt25"><span style="width:${(t.index+1)*100/n}%"></span></div>${n===20?`<div class="quiz-section">${L(t.index<7?'section1':t.index<14?'section2':'section3')}</div>`:''}<h3 class="mt15" style="font-size:19px">${t.index+1}. ${esc(q[lang])}</h3>${q['options_'+lang].map((option,i)=>`<label class="choice"><input type="radio" name="ttopt" ${t.answers[t.index]===i?'checked':''} onchange="ttChoose(${i})"> <span><strong class="answer-letter">${LETTERS[i]})</strong> ${esc(option)}</span></label>`).join('')}<div class="row spread mt25"><button class="btn outline" ${t.index===0?'disabled':''} onclick="ttMove(-1)">← ${L('back')}</button><button class="btn primary" onclick="ttMove(1)">${t.index===n-1?L('completeQuiz')+' ✓':L('next')+' →'}</button></div><div class="subdued minor mt15">${Object.keys(t.answers).length}/${n}</div></div></div>`;}
function ttAdminUI(){const list=admin.teacherAttempts||[],avg=list.length?(list.reduce((a,x)=>a+x.score,0)/list.length).toFixed(1):'—';const locale=lang==='kk'?'kk-KZ':'ru-RU';
 return `<div class="numbers"><div class="number-tile"><span>👩‍🏫 ${L('ttCount')}</span><b>${list.length}</b></div><div class="number-tile"><span>📊 ${L('ttAvg')}</span><b>${avg}</b></div></div>
 <div class="panel"><div class="row spread"><div><h2>👩‍🏫 ${L('ttResults')}</h2><p class="subdued" style="margin:0">${L('ttResultsDesc')}</p></div><a class="btn outline small" href="/api/admin/teacher-csv" download>↓ Excel / CSV</a></div>
 <p class="note mt15">🔗 ${L('ttLink')}</p>
 ${list.length?`<div class="tt-table-wrap mt15"><table class="tt-table"><thead><tr><th>#</th><th>${L('ttName')}</th><th>${L('ttScore')}</th><th>${L('level')}</th><th>${L('ttDate')}</th><th></th></tr></thead><tbody>${list.map((a,i)=>`<tr><td>${list.length-i}</td><td>${esc(a.name)}</td><td><b>${a.score}</b>/${a.total}</td><td>${L(levelKey(a.score))}</td><td>${esc(new Date(a.finishedAt).toLocaleString(locale))}</td><td><button class="btn softred small" onclick="ttDelete(${a.id})">${L('ttDelete')}</button></td></tr>`).join('')}</tbody></table></div><div class="row mt15"><button class="btn softred small" onclick="ttClear()">🗑 ${L('ttClear')}</button></div>`:`<p class="subdued mt15">${L('ttNone')}</p>`}</div>
 <div class="mt25">${card('🔑 '+L('ttCodeTitle'),L('ttCodeHelp'),`<div class="row">${field(L('ttCode'),'ttAdminCode',admin.teacherTestCode||'','text','','maxlength="60" autocomplete="off"')}<button class="btn primary" onclick="ttSaveCode()">${L('ttSaveCode')}</button></div>`)}</div>`;}
async function ttSaveCode(){await post('/admin/teacher-test',{action:'code',code:$('ttAdminCode').value.trim()});}
async function ttDelete(id){if(!confirm(L('ttDelete')+'?'))return;await post('/admin/teacher-test',{action:'delete',id});}
async function ttClear(){if(!confirm(L('ttClearConfirm')))return;await post('/admin/teacher-test',{action:'clear',confirm:'CLEAR'});}
$('brandSecret').addEventListener('click',()=>{if(pub?.teacher){changeView('overview');return;}if(pub?.member){note(L('student'));return;}$('teacherDialog').showModal();$('teacherPassword').focus();});
$('teacherForm').addEventListener('submit',teacherLogin);
$('dialogClose').addEventListener('click',()=>$('teacherDialog').close());
$('teacherDialog').addEventListener('click',event=>{if(event.target===$('teacherDialog'))$('teacherDialog').close();});
$('langRu').addEventListener('click',()=>setLanguage('ru'));
$('langKk').addEventListener('click',()=>setLanguage('kk'));
$('signout').addEventListener('click',logout);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
setInterval(async()=>{if(!pub||pub.teacher||ttest||document.hidden)return;const focused=document.activeElement?.matches('input, textarea, select');if(focused||document.querySelector('#answerPhoto')?.files.length)return;try{const p=await api('/public');if(p.phase!==pub.phase||p.member!==pub.member||JSON.stringify(p.leaderboard)!==JSON.stringify(pub.leaderboard)){await refresh();}}catch{}},13000);
refresh();
